359→/// Find the first high-confidence fix for the given error output and context.
360→pub fn find_fix(error_output: &str, context: &StepContext) -> Option<FixSuggestion> {
361→    for pattern in built_in_patterns() {
362→        if pattern.confidence != Confidence::High {
363→            continue;
364→        }
365→        if !pattern.context.matches(context) {
366→            continue;
367→        }
368→        let re = Regex::new(pattern.regex).ok()?;
369→        if let Some(caps) = re.captures(error_output) {
370→            if let Some(fix) = (pattern.suggest)(&caps, context) {
371→                return Some(fix);
372→            }
373→        }
374→    }
375→    None
376→}
377→
378→/// Find the first low-confidence hint for the given error output and context.
379→pub fn find_hint(error_output: &str, context: &StepContext) -> Option<String> {
380→    for pattern in built_in_patterns() {
381→        if pattern.confidence != Confidence::Low {
382→            continue;
383→        }
384→        if !pattern.context.matches(context) {
385→            continue;
386→        }
387→        let re = Regex::new(pattern.regex).ok()?;
388→        if let Some(caps) = re.captures(error_output) {
389→            if let Some(fix) = (pattern.suggest)(&caps, context) {
390→                return Some(format!("You might try: {}", fix.label));
391→            }
392→        }
393→    }
394→    None
395→}
