    fn mock_ui_error_block_empty_output_not_captured_as_message() {
        let mut ui = MockUI::new();

        ui.show_error_block("failing_cmd", "", None);

        assert!(ui.messages().is_empty());
        assert!(ui.has_error("failing_cmd"));
    }

