    fn format_status_contains_icon_or_bracket() {
        let mut ui = MockUI::new();
        let status = ui.format_status(StatusKind::Blocked, "Blocked (dependency failed)");
        // Should contain the icon or bracket form
        assert!(
            status.contains(StatusKind::Blocked.icon())
                || status.contains(StatusKind::Blocked.bracketed())
        );
    }
