        // "command not found: xyz" triggers the low-confidence command_not_found pattern
        let mut steps = HashMap::new();
        steps.insert(
            "broken".to_string(),
            make_step(
                "broken",
                "echo 'command not found: xyz' >&2; exit 127",
                vec![],
            ),
        );

        let runner = WorkflowRunner::new(&config, steps);
